function paintSound() { if ($("#setPage") && !$("#setPage").hidden) renderSettings(); }
setInterval(() => Snd.mode(inMatch() || (Q.s && Q.s.phase === "run") ? "game" : "lobby"), 1500);

/* ---------- ambient particles ---------- */
const fx = $("#fx"), fctx = fx.getContext("2d");
let parts = [], glowCol = "#A855F7", accCol = "#7CF5C8";
